'use strict';

// MODULES //

var toWord = require('@stdlib/number/float32/base/to-word');
var fromWord = require('@stdlib/number/float32/base/from-word');
var isnanf = require('@stdlib/math/base/assert/is-nanf');
var kernelLog1pf = require('@stdlib/math/base/special/kernel-log1pf');
var NINF = require('@stdlib/constants/float32/ninf');


// VARIABLES //

var TWO25 = 3.3554432000e+07;     // 0x4c000000
var IVLN10 = 4.3429449201e-01;    // 0x3ede5bd9
var LOG10_2HI = 3.0102999566e-01; // 0x3e9a209a
var LOG10_2LO = 3.6942390772e-13; // 0x2d022b36

// 0x7f800000 = 2139095040
var FLT_MAX_EXP_BIT_MASK = 0x7f800000;

// 0x00800000 = 8388608
var FLT_MIN_NORMAL_EXP = 0x00800000;

// 0x3f800000 = 1065353216 => bias 127
var FLT_BIAS_EXP = 0x3f800000;


// MAIN //

/**
* Evaluates the common logarithm (base ten) of a single-precision floating-point number.
*
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var v = log10f( 100.0 );
* // returns 2.0
*/
function log10f(x) {
    var hfsq;
    var hi;
    var lo;
    var r;
    var f;
    var y;
    var hx;
    var i;
    var k;

    if (x === 0.0) {
        return NINF;
    }
    if (isnanf(x) || x < 0.0) {
        return NaN;
    }
    hx = toWord(x);
    k = 0;
    if (hx < FLT_MIN_NORMAL_EXP) {
        // x < 2**-126
        if ((hx & 0x7fffffff) === 0) {
            return NINF; // log(+-0) = -inf
        }
        k -= 25;
        x *= TWO25; // subnormal number, scale up x
        hx = toWord(x);
    }
    if (hx >= FLT_MAX_EXP_BIT_MASK) {
        return x + x;
    }
    if (hx === FLT_BIAS_EXP) {
        return 0.0; // log(1) = +0
    }
    k += (hx >>> 23) - 127;
    hx &= 0x007fffff;
    i = (hx + 0x95f64) & 0x800000;
    // Normalize x or x/2...
    x = fromWord(hx | (i ^ FLT_BIAS_EXP));
    k += (i >>> 23);
    y = k;
    f = x - 1.0;
    hfsq = 0.5 * f * f;
    r = kernelLog1pf(f);

    hi = f - hfsq;
    hx = toWord(hi);
    hi = fromWord(hx & 0xfffff000);
    lo = (f - hi) - hfsq + r;
    return (y * LOG10_2LO) + ((lo + hi) * IVLN10) + (y * LOG10_2HI);
}


// EXPORTS //

module.exports = log10f;
